using System.Collections; using System.Collections.Generic; using UnityEngine; namespace MyLumo { public class CommandExecutor:MonoBehaviour { public LumoController lumo; public bool IsBusy{get;private set;} public string CurrentCommand{get;private set;} readonly Queue<string> q=new(); public void Enqueue(string c){if(string.IsNullOrWhiteSpace(c))return;q.Enqueue(c.Trim());if(!IsBusy)StartCoroutine(Run());} IEnumerator Run(){IsBusy=true;while(q.Count>0){CurrentCommand=q.Dequeue();foreach(var t in CommandPlanner.Plan(CurrentCommand))yield return lumo.ExecuteTask(t);GameStatePersistence.Instance?.SaveNow();}CurrentCommand="";IsBusy=false;} } }
